// Geo Redirect Script - redirect users based on country
(function() {
    var trackerUrl = '${Z}';
    var campaignId = 'YOUR_CAMPAIGN_ID';
    
    // Mapping: country code -> offer URL
    var geoOffers = {
        'RU': 'https://offer1.com',
        'DE': 'https://offer2.com',
        'ES': 'https://offer3.com',
        'US': 'https://offer4.com',
        'DEFAULT': 'https://default-offer.com'
    };
    
    fetch(trackerUrl + '/api.php?action=detect_geo')
        .then(r => r.json())
        .then(data => {
            var country = data.country || 'DEFAULT';
            var url = geoOffers[country] || geoOffers['DEFAULT'];
            
            // Track click and redirect
            var clickUrl = trackerUrl + '/click.php?campaign_id=' + campaignId + 
                '&sub1=' + country + '&redirect=0';
            
            fetch(clickUrl).finally(() => {
                window.location.href = url;
            });
        })
        .catch(() => {
            window.location.href = geoOffers['DEFAULT'];
        });
})();
